import { serve } from "srvx";
import { staticMiddleware } from "srvx/static";
import type { TestProject } from "vite-plus/test/node";

export default async function setup(project: TestProject) {
  if (process.env.E2E_BASE_URL) {
    const response = await fetch(process.env.E2E_BASE_URL, { signal: AbortSignal.timeout(10_000) });
    if (!response.ok) throw new Error(`E2E server returned ${response.status}`);
    return;
  }

  // @ts-ignore -- Generated by website:build and absent before the build runs.
  const { default: handler } = await import("../dist/server/server.js");
  const server = serve({
    port: 0,
    fetch: (request) => handler.fetch(request),
    middleware: [staticMiddleware({ dir: "./dist/client" })],
  });
  await server.ready();
  const options = project.config.provide.e2e!;
  project.provide("e2e", {
    ...options,
    contextOptions: { ...options.contextOptions, baseURL: server.url },
  });
  return async () => {
    await server.close();
  };
}
